function validate([encodedText, rows]) {
  if (!Number.isInteger(rows) || rows < 1 || rows > 1000) return 'rows is between 1 and 1000.';
  if (encodedText.length > 1000000) return 'encodedText has at most 10^6 characters.';
  if (!/^[a-z ]*$/.test(encodedText)) return 'encodedText uses lowercase letters and spaces only.';
  if (encodedText.length % rows !== 0) return 'The length of encodedText must be a multiple of rows.';
  const cols = encodedText.length / rows;
  if (cols === 0) return null;
  for (let r = 1; r < rows; r++) for (let c = 0; c < Math.min(r, cols); c++) if (encodedText[r * cols + c] !== ' ') return 'Cells left of the first diagonal must hold spaces.';
  let index = 0, lastLetter = -1;
  for (let j = 0; j < cols; j++) for (let r = 0; r < rows && j + r < cols; r++, index++) if (encodedText[r * cols + j + r] !== ' ') lastLetter = index;
  const j0 = Math.max(0, cols - rows);
  if (lastLetter < j0 * rows + cols - 1 - j0) return 'The rightmost column must hold part of the text.';
  return null;
}

