function decodeCiphertext(encodedText, rows) {
  const cols = encodedText.length / rows;
  const chars = [];

  for (let start = 0; start < cols; start++) {
    let r = 0;
    let c = start;
    while (r < rows && c < cols) {
      chars.push(encodedText[r * cols + c]);
      r++;
      c++;
    }
  }
  return chars.join('').trimEnd();
}

