function decodeCiphertext(encodedText, rows) {
  const width = encodedText.length / rows;
  const grid = [];
  for (let r = 0; r < rows; r++) grid.push(encodedText.slice(r * width, (r + 1) * width));
  // Every cell on or right of the main diagonal belongs to the diagonal starting at column c - r.
  const cells = [];
  for (let r = 0; r < rows; r++) for (let c = r; c < width; c++) cells.push({ key: (c - r) * rows + r, ch: grid[r][c] });
  cells.sort((a, b) => a.key - b.key);
  return cells.map(cell => cell.ch).join('').replace(/ +$/, '');
}

