function generate(rand, size) {
  const capacity = (rows, cols) => { let total = 0; for (let j = 0; j < cols; j++) total += Math.min(rows, cols - j); return total; };
  // Index, in diagonal order, of the first cell that lies in the rightmost column.
  const firstInLast = (rows, cols) => { const j0 = Math.max(0, cols - rows); return j0 * rows + cols - 1 - j0; };
  let rows, cols, length;
  if (size === 'large') {
    const pick = rand();
    rows = pick < 0.4 ? 1 + Math.floor(rand() * 20) : pick < 0.8 ? 20 + Math.floor(rand() * 181) : 200 + Math.floor(rand() * 801);
    cols = Math.floor(10000 / rows);
    const low = firstInLast(rows, cols) + 1, high = capacity(rows, cols);
    length = low + Math.floor(rand() * (high - low + 1));
  } else {
    rows = 1 + Math.floor(rand() * 6);
    length = rand() < 0.1 ? 0 : 1 + Math.floor(rand() * 12);
    if (length === 0) return ['', rows];
    cols = 1;
    while (capacity(rows, cols) < length) cols++;
    // Any column count whose rightmost column is reached by the text is a valid choice.
    while (rand() < 0.4 && firstInLast(rows, cols + 1) <= length - 1) cols++;
  }
  const spaceChance = rand() * 0.4;
  const text = [];
  for (let i = 0; i < length; i++) text.push(rand() < spaceChance ? ' ' : String.fromCharCode(97 + Math.floor(rand() * 26)));
  text[length - 1] = String.fromCharCode(97 + Math.floor(rand() * 26));
  const grid = Array.from({ length: rows }, () => new Array(cols).fill(' '));
  let k = 0;
  for (let j = 0; j < cols; j++) for (let r = 0; r < rows && j + r < cols; r++) if (k < length) grid[r][j + r] = text[k++];
  return [grid.map(row => row.join('')).join(''), rows];
}
